            "headlinePongal": "थै पोंगल — द्वार के लिए फसल का पाठ।",
            "headlineDiwali": "दीपावली — दीयों के साथ द्वार पर प्रकाश।",
            "headlineNavratri": "नवरात्रि — नौ रातों का कमल पाठ।",
            "headlineOnam": "ओणम — चूर्ण में खींचा पूकलम पाठ।",
            "headlineUgadi": "उगादी और पुथाण्डु — वर्ष द्वार पर खुलता है।",
            "headlineNewYear": "नव वर्ष के लिए उगते सूर्य का पाठ।",
            "headlineThreshold": "रोज़ का प्रातः कोलम, घर और चींटियों के लिए।",
            "stepStart1": "कोलम के हृदय से शुरू करें और पहली वक्र निकटतम दो बिंदुओं पर टिकाएँ।",
            "stepStart2": "केंद्र के चारों ओर शांत रेखा खींचें, कलाई हल्की रखें।",
            "stepStart3": "विपरीत दिशा की पंखुड़ी प्रतिबिम्बित करें ताकि संतुलन रहे।",
            "stepMid1": "आटे की रेखा उठाए बिना अगले बिंदु-युग्म के चारों ओर घूमें।",
            "stepMid2": "वक्र बिंदुओं को चूमे, उन्हें काटे नहीं।",
            "stepMid3": "अंतर समान रखें — पारंपरिक कोलम लय में जीता है।",
            "stepMid4": "सजावटी घुमाव जोड़ें, फिर केंद्र की ओर लौटें।",
            "stepEnd1": "बाहरी सीमा बंद करें और अंतिम रेखा आरंभ बिंदु पर टिकाएँ।",
            "stepEnd2": "कोनों को नरम करें ताकि रंगोली हाथ से खींची लगे।",
            "stepEnd3": "शांत केंद्र चिह्न से समाप्त करें, जैसे चावल का बिंदु।",
