            "pattern.eight-petal.title": "अष्टदल कमल",
            "pattern.eight-petal.note": "आठ पंखुड़ियाँ पूरा द्वार कमल बनाती हैं — मंदिर ज्यामिति।",
            "pattern.geo-star.title": "ज्यामितीय तारा",
            "pattern.geo-star.note": "तारा ज्यामिति नए आरंभ के लिए — शांत, सम बिंदु।",
            "pattern.festival-flower.title": "त्योहार फूल रंगोली",
            "pattern.festival-flower.note": "गेंदे की पंखुड़ियाँ तब जब घर में मेहमान अपेक्षित हों।",
            "pattern.mandala.title": "मंडल रंगोली",
            "pattern.mandala.note": "परतदार मंडल एक लंबी एकाग्रता है, अक्सर नवरात्रि और नव वर्ष पर।",
            "pattern.butterfly.title": "तितली रंगोली",
            "pattern.butterfly.note": "वसंत आंगन ओणम और उगादी पर तितलियाँ खींचते हैं।",
            "pattern.pongal-pot.title": "पोंगल हांडी रंगोली",
            "pattern.pongal-pot.note": "उफनती हांडी थै पोंगल है — फसल द्वार पर।",
            "pattern.sikku-knot.title": "सिक्कु गांठ कोलम",
            "pattern.sikku-knot.note": "सिक्कु गांठ तमिल क्लासिक है — रेखा नहीं टूटती।",
            "pattern.onam-pookalam.title": "ओणम पूकलम",
            "pattern.onam-pookalam.note": "पूकलम केरल का ओणम फूल-कालीन है; यह पाठ वे वलय चावल में खींचता है।",
            "pattern.sun-burst.title": "नव वर्ष सूर्य",
            "pattern.sun-burst.note": "पुथाण्डु और उगादी के लिए उगता सूर्य — वर्ष द्वार पर खुलता है।",
