            "thresholdKicker": "இன்றைய வாசல் கோலம்",
            "headlinePongal": "தைப் பொங்கல் — வாசலுக்கு அறுவடைப் பாடம்.",
            "headlineDiwali": "தீபாவளி — விளக்குகளுடன் வாசலில் ஒளி.",
            "headlineNavratri": "நவராத்திரி — ஒன்பது இரவுகளின் தாமரைப் பாடம்.",
            "headlineOnam": "ஓணம் — மாவில் வரையும் பூக்கோலப் பாடம்.",
            "headlineUgadi": "உகாதி மற்றும் புத்தாண்டு — ஆண்டு வாசலில் திறக்கிறது.",
            "headlineNewYear": "புத்தாண்டுக்கான உதய சூரியப் பாடம்.",
            "headlineThreshold": "தினசரி காலைக் கோலம், வீட்டிற்கும் எறும்புகளுக்கும்.",
            "stepStart1": "கோலத்தின் நடுவிலிருந்து தொடங்கி, முதல் வளைவை அருகிலுள்ள இரண்டு புள்ளிகளில் வை.",
            "stepStart2": "நடுவைச் சுற்றி அமைதியான மாவுக் கோடு; மணிக்கட்டு இலேசாக.",
            "stepStart3": "எதிர்ப் பக்க இதழை எதிரொலித்துச் சமநிலை காத்துக்கொள்.",
            "stepMid1": "மாவைத் தூக்காமல் அடுத்த புள்ளி இணையைச் சுற்று.",
            "stepMid2": "வளைவு புள்ளிகளை முத்தமிடட்டும், வெட்ட வேண்டாம்.",
            "stepMid3": "இடைவெளி சமமாக — பாரம்பரியக் கோலம் தாளத்தில் வாழ்கிறது.",
            "stepMid4": "அலங்கார வளையத்தைச் சேர்த்து நடுவுக்குத் திரும்பு.",
            "stepEnd1": "வெளி வளையத்தை மூடி, கடைசிக் கோட்டைத் தொடக்கத்தில் வை.",
            "stepEnd2": "மூலைகளை மென்மையாக்கி, கைவரை போல் இருக்கட்டும்.",
            "stepEnd3": "அமைதியான நடுப் புள்ளியுடன் முடி — அரிசிப் புள்ளி போல.",
            "freehandTitle": "கைவரை ரங்கோலி",
