            "colorPurple": "ஊதா",
            "colorGold": "பொன்",
            "pattern.lotus-dot.title": "தாமரைப் புள்ளி கோலம்",
            "pattern.lotus-dot.note": "தாமரை வாசலில் வரவேற்பு — தூய, சுபமான அடிக்கு பத்மம்.",
            "pattern.simple-flower.title": "எளிய பூக்கோலம்",
            "pattern.simple-flower.note": "சிறிய பூக்கோலம் வீடு விழிப்பதற்கு முன் அன்றாட வணக்கம்.",
            "pattern.peacock.title": "மயில் கோலம்",
            "pattern.peacock.note": "மயில் கோலம் திருவிழாக் காட்சி: விருந்தினர் வரும்போது வாசல் அழகு.",
            "pattern.diya.title": "தீபக் கோலம்",
            "pattern.diya.note": "தீபாவளியில் தீபக் கோலம் — விளக்கும் தரையும் ஒன்றாகப் பேசும்.",
            "pattern.pulli.title": "புள்ளி கோலம்",
            "pattern.pulli.note": "புள்ளி கோலம் தமிழ் காலை எழுத்து: அரிசிப் புள்ளிகள், பின் ஒரு கோடு — எறும்புகளுக்கும்.",
            "pattern.spiral.title": "சுழல் சிக்கு",
            "pattern.spiral.note": "சிக்கு சுழல் மாவைத் தூக்காமல் கைக்குப் பயிற்சி, புள்ளிகளைச் சுற்றிய தொடர் ஆசி.",
            "pattern.eight-petal.title": "எட்டு இதழ்த் தாமரை",
            "pattern.eight-petal.note": "எட்டு இதழ்கள் முழு வாசல் தாமரை — கோயில் வடிவத்தின் அஷ்டதளம்.",
            "pattern.geo-star.title": "நட்சத்திர கோலம்",
            "pattern.geo-star.note": "நட்சத்திர வடிவம் புதிய தொடக்கங்களுக்கு — வாசலில் அமைதியான முனைகள்.",
            "pattern.festival-flower.title": "திருவிழாப் பூக்கோலம்",
            "pattern.festival-flower.note": "சமந்தி இதழ்கள் விருந்தினர் எதிர்பார்க்கும் வீட்டின் திருவிழாத் தரை.",
            "pattern.mandala.title": "மண்டல கோலம்",
            "pattern.mandala.note": "அடுக்கு மண்டலம் நீண்ட ஒருமுகப்பாடு, நவராத்திரி மற்றும் புத்தாண்டில்.",
            "pattern.butterfly.title": "வண்ணத்துப்பூச்சி",
            "pattern.butterfly.note": "வசந்த முற்றங்கள் ஓணம், உகாதிக்கு வண்ணத்துப்பூச்சி — களிமண் மீது தோட்டம்.",
            "pattern.pongal-pot.title": "பொங்கல் பானை",
            "pattern.pongal-pot.note": "பொங்கும் பானை தைப்பொங்கல்: அறுவடை வாசலில்.",
            "pattern.sikku-knot.title": "சிக்கு முடிச்சு கோலம்",
            "pattern.sikku-knot.note": "சிக்கு முடிச்சு தமிழ் செவ்வியல் — கோடு முரியாது, வீடு ஒரு நூலில் கட்டுப்படும்.",
            "pattern.onam-pookalam.title": "ஓணம் பூக்கோலம்",
            "pattern.onam-pookalam.note": "பூக்கோலம் கேரள ஓணப் பூ விரிப்பு; இந்தப் பாடம் அந்த வளையங்களை அரிசி மாவில் வரைகிறது.",
            "pattern.sun-burst.title": "புத்தாண்டு சூரியன்",
            "pattern.sun-burst.note": "புத்தாண்டுக்கும் உகாதிக்கும் உதய சூரியன் — ஆண்டு வாசலில் திறக்கிறது.",
            "pattern.mango-leaf.title": "மாவிலைத் தோரணம்",
            "pattern.mango-leaf.note": "மாவிலைத் தோரணம் உகாதி, தீபாவளியில் தொங்கவிடப்பட்டு வரையப்படும் உயிருள்ள வரவேற்பு.",
