            "pattern.peacock.title": "മയിൽ റംഗോലി",
            "pattern.peacock.note": "മയിൽ റംഗോലി ഉത്സവ കാഴ്ച: അതിഥികൾ വരുമ്പോൾ പടിയുടെ സൗന്ദര്യം.",
            "pattern.diya.title": "ദീപ റംഗോലി",
            "pattern.diya.note": "ദീപാവലിയിൽ ദീപ കോലം — വിളക്കും തറയും ഒന്നിച്ച് സംസാരിക്കാൻ.",
            "pattern.pulli.title": "പാരമ്പര്യ പുള്ളി കോലം",
            "pattern.pulli.note": "പുള്ളി കോലം തമിഴ് പ്രഭാത എഴുത്ത്: അരി പുള്ളികൾ, പിന്നെ ഒരു വര — ഉറുമ്പുകൾക്കും.",
            "pattern.spiral.title": "ചുഴൽ കോലം",
            "pattern.spiral.note": "സിക്കു ചുഴൽ മാവ് ഉയർത്താതെ കൈ പഠിപ്പിക്കുന്നു.",
            "pattern.eight-petal.title": "എട്ട് ഇതൾ താമര",
            "pattern.eight-petal.note": "എട്ട് ഇതളുകൾ പൂർണ്ണ പടി താമര — ക്ഷേത്ര ജ്യാമിതി.",
            "pattern.geo-star.title": "ജ്യാമിതീയ നക്ഷത്രം",
            "pattern.geo-star.note": "നക്ഷത്രം പുതിയ തുടക്കങ്ങൾക്ക് — പടിയിലെ ശാന്ത മൂലകൾ.",
            "pattern.festival-flower.title": "ഉത്സവ പൂ റംഗോലി",
            "pattern.festival-flower.note": "ചെണ്ടുമല്ലി ഇതളുകൾ അതിഥികളെ കാത്തിരിക്കുന്ന വീட்டிൻ്റെ ഉത്സവ തറ.",
            "pattern.mandala.title": "മണ്ഡല റംഗോലി",
            "pattern.mandala.note": "പാളികളുള്ള മണ്ഡലം ദീർഘ ഏകാഗ്രത, പലപ്പോഴും നവരാത്രിയും പുതുവർഷവും.",
            "pattern.butterfly.title": "ചിത്രശലഭ റംഗോലി",
            "pattern.butterfly.note": "വസന്ത മുറ്റങ്ങൾ ഓണത്തിനും ഉഗാദിക്കും ചിത്രശലഭങ്ങൾ — കളിമണ്ണിലെ പൂന്തോട്ടം.",
            "pattern.pongal-pot.title": "പൊങ്കൽ കലം റംഗോലി",
            "pattern.pongal-pot.note": "പൊങ്ങുന്ന കലം തൈ പൊങ്കൽ — വിളവെടുപ്പ് പടിക്കൽ.",
            "pattern.sikku-knot.title": "സിക്കു കെട്ട് കോലം",
            "pattern.sikku-knot.note": "സിക്കു കെട്ട് തമിഴ് ക്ലാസിക് — വര മുറിയില്ല.",
            "pattern.onam-pookalam.title": "ഓണം പൂക്കളം",
            "pattern.onam-pookalam.note": "പൂക്കളം കേരളത്തിന്റെ ഓണ പൂപ്പരവതാനി; ഈ പാഠം ആ വളയങ്ങൾ അരിമാവിൽ വരയ്ക്കുന്നു.",
            "pattern.sun-burst.title": "പുതുവർഷ സൂര്യൻ",
            "pattern.sun-burst.note": "പുത്താണ്ടിനും ഉഗാദിക്കും ഉദയസൂര്യൻ — വർഷം പടിക്കൽ തുറക്കുന്നു.",
            "pattern.mango-leaf.title": "മാവില തോരണം",
            "pattern.mango-leaf.note": "മാവില തോരണം ഉഗാദിയിലും ദീപാവലിയിലും ജീവനുള്ള സ്വാഗതം.",
