            "headlineThreshold": "ପ୍ରତିଦିନ ସକାଳ କୋଲମ୍, ଘର ଏବଂ ପିମ୍ପୁଡ଼ି ପାଇଁ।",
            "stepStart1": "Begin at the heart of the kolam and rest the first curve on the nearest two dots.",
            "stepStart2": "Trace a calm powder line around the center, keeping the wrist light.",
            "stepStart3": "Mirror the petal on the opposite side so the rangoli stays balanced.",
            "stepMid1": "Sweep around the next pair of dots without lifting the powder line.",
            "stepMid2": "Let the curve kiss the dots rather than cutting through them.",
            "stepMid3": "Keep the spacing even — traditional kolam lives in rhythm.",
            "stepMid4": "Add the decorative loop, then return toward the center.",
            "stepEnd1": "Close the outer border and rest the last stroke on the starting point.",
            "stepEnd2": "Soften the corners so the rangoli feels hand-drawn, not rigid.",
            "stepEnd3": "Finish with a quiet center mark, like a bindu of rice powder.",
