            "stepMid4": "Añade el bucle decorativo y vuelve al centro.",
            "stepEnd1": "Cierra el borde exterior y apoya el último trazo en el inicio.",
            "stepEnd2": "Suaviza las esquinas para que se sienta dibujado a mano.",
