            "pattern.lotus-dot.title": "Rangoli de loto con puntos",
            "pattern.lotus-dot.note": "El loto se dibuja en la puerta como bienvenida: padma para un umbral limpio y auspicioso.",
            "pattern.simple-flower.title": "Kolam de flor sencilla",
            "pattern.simple-flower.note": "Un pequeño kolam floral es el saludo diario antes de que despierte la casa.",
            "pattern.peacock.title": "Rangoli de pavo real",
            "pattern.peacock.note": "El pavo real es una vista de fiesta: belleza en el umbral cuando se espera visita.",
            "pattern.diya.title": "Rangoli de diya",
            "pattern.diya.note": "El kolam de diya se dibuja en Deepavali para que lámpara y suelo hablen juntos.",
            "pattern.pulli.title": "Kolam pulli tradicional",
            "pattern.pulli.note": "El kolam pulli es escritura matutina tamil: puntos de harina y una línea que los rodea, también para las hormigas.",
            "pattern.spiral.title": "Kolam en espiral",
            "pattern.spiral.note": "La espiral sikku entrena la mano a no levantar la harina: una bendición continua.",
