            "pattern.eight-petal.note": "Ocho pétalos forman el loto completo del umbral, la forma ashtadala del templo.",
            "pattern.geo-star.title": "Estrella geométrica",
            "pattern.geo-star.note": "La estrella se dibuja para comienzos nuevos: puntas tranquilas y pares en el peldaño.",
            "pattern.festival-flower.title": "Rangoli floral de fiesta",
            "pattern.festival-flower.note": "Los pétalos de cempasúchil son el suelo habitual cuando la casa espera compañía.",
            "pattern.mandala.title": "Rangoli mandala",
            "pattern.mandala.note": "Un mandala en capas es un voto más largo de concentración, a menudo en Navratri y año nuevo.",
            "pattern.butterfly.title": "Rangoli de mariposa",
            "pattern.butterfly.note": "Los patios de primavera dibujan mariposas para Onam y Ugadi: un jardín sobre la arcilla.",
            "pattern.pongal-pot.title": "Rangoli de olla Pongal",
            "pattern.pongal-pot.note": "La olla que rebosa es Thai Pongal: cosecha y alegría en la puerta.",
            "pattern.sikku-knot.title": "Kolam de nudo sikku",
            "pattern.sikku-knot.note": "Los nudos sikku son un clásico tamil: la línea no se rompe, la casa queda unida en un hilo.",
            "pattern.onam-pookalam.title": "Pookalam de Onam",
            "pattern.onam-pookalam.note": "El pookalam es la alfombra floral de Onam en Kerala; esta lección dibuja esos anillos en harina.",
            "pattern.sun-burst.title": "Sol de año nuevo",
            "pattern.sun-burst.note": "Un sol naciente para Puthandu y Ugadi: el año se abre en el umbral.",
            "pattern.mango-leaf.title": "Toran de hoja de mango",
            "pattern.mango-leaf.note": "El toran de mango se cuelga y se dibuja en Ugadi y Deepavali como bienvenida viva.",
