            "pattern.lotus-dot.title": "蓮の点ランゴリ",
            "pattern.lotus-dot.note": "蓮は戸口の歓迎——清らかで吉祥な一歩のパドマ。",
            "pattern.simple-flower.title": "シンプルな花コーラム",
            "pattern.simple-flower.note": "小さな花コーラムは、家が起きる前の毎日のあいさつ。",
            "pattern.peacock.title": "孔雀ランゴリ",
            "pattern.peacock.note": "孔雀ランゴリは祭りの眺め。客を待つ敷居の美。",
            "pattern.diya.title": "ディヤ・ランゴリ",
            "pattern.diya.note": "ディーパーヴァリにディヤ・コーラムを描き、灯と床が共に語る。",
            "pattern.pulli.title": "伝統プッリ・コーラム",
            "pattern.pulli.note": "プッリ・コーラムはタミルの朝の文字。米粉の点、それを巡る一本の線——蟻のためでもある。",
            "pattern.spiral.title": "螺旋コーラム",
            "pattern.spiral.note": "シックの螺旋は粉を上げない手を育てる。点のまわりの続く祝福。",
            "pattern.eight-petal.title": "八弁の蓮",
            "pattern.eight-petal.note": "八弁は戸口の蓮を完成させる。寺院幾何のアシュタダラ。",
            "pattern.geo-star.title": "幾何の星",
            "pattern.geo-star.note": "星の幾何は新しい始まりのため。段の上の静かな尖り。",
            "pattern.festival-flower.title": "祭りの花ランゴリ",
            "pattern.festival-flower.note": "マリーゴールドの花弁は、客を待つ家の祭りの床。",
            "pattern.mandala.title": "マンダラ・ランゴリ",
            "pattern.mandala.note": "層のマンダラは長い集中の誓い。ナヴァラートリと新年に多い。",
            "pattern.butterfly.title": "蝶のランゴリ",
            "pattern.butterfly.note": "春の中庭はオーナムとウガディに蝶を描く。粘土の上の庭。",
            "pattern.pongal-pot.title": "ポンガル鍋ランゴリ",
            "pattern.pongal-pot.note": "溢れ鍋はタイ・ポンガル。収穫が戸口に来る。",
            "pattern.sikku-knot.title": "シック結びコーラム",
            "pattern.sikku-knot.note": "シック結びはタミルの古典。線は切れず、家は一本の糸に結ばれる。",
            "pattern.onam-pookalam.title": "オーナムのプーカラム",
            "pattern.onam-pookalam.note": "プーカラムはケーララのオーナムの花絨毯。このレッスンは米粉でその輪を描く。",
            "pattern.sun-burst.title": "新年の朝日",
            "pattern.sun-burst.note": "プタンドゥとウガディの朝日。年は敷居で開く。",
            "pattern.mango-leaf.title": "マンゴー葉のトーラン",
            "pattern.mango-leaf.note": "マンゴー葉のトーランはウガディとディーパーヴァリの生きた歓迎。",
        ],
