            "headlineOnam": "欧南节——用米粉绘制的花毯课。",
            "headlineUgadi": "乌加迪与泰米尔新年——一年从台阶开启。",
            "headlineNewYear": "为新年准备的朝阳课。",
            "headlineThreshold": "日常清晨科拉姆，为家与蚂蚁而画。",
            "stepStart1": "从科拉姆中心开始，把第一道弯落在最近的两点上。",
            "stepStart2": "绕着中心轻轻描一条米粉线，手腕放轻。",
            "stepStart3": "在对面镜像花瓣，让兰戈利保持平衡。",
            "stepMid1": "不抬起米粉线，绕过下一对点。",
            "stepMid2": "让曲线轻触点，而不是穿过它们。",
            "stepMid3": "间距要均匀——传统科拉姆活在节奏里。",
            "stepMid4": "加上装饰环，再回到中心。",
            "stepEnd1": "合上外圈，把最后一笔落回起点。",
            "stepEnd2": "把转角画软，让它像手绘，而不是尺子。",
            "stepEnd3": "以安静的中心点收笔，像一粒米粉。",
