            "pattern.lotus-dot.title": "莲花点阵兰戈利",
            "pattern.lotus-dot.note": "莲花画在门口作欢迎——净洁、吉祥的一步。",
            "pattern.simple-flower.title": "简易花卉科拉姆",
            "pattern.simple-flower.note": "小花科拉姆是房屋醒来前的日常问候。",
            "pattern.peacock.title": "孔雀兰戈利",
            "pattern.peacock.note": "孔雀兰戈利是节日景象：宾客将至时门槛的美。",
            "pattern.diya.title": "油灯兰戈利",
            "pattern.diya.note": "排灯节画油灯科拉姆，让灯与地面一起说话。",
            "pattern.pulli.title": "传统点阵科拉姆",
            "pattern.pulli.note": "点阵科拉姆是泰米尔清晨书写：米粉点，再绕点一笔——也为蚂蚁留下。",
            "pattern.spiral.title": "螺旋科拉姆",
            "pattern.spiral.note": "连环螺旋训练手不抬粉，绕点的连续祝福。",
            "pattern.eight-petal.title": "八瓣莲花",
            "pattern.eight-petal.note": "八瓣组成完整的门口莲花，是神庙几何中的八瓣形。",
            "pattern.geo-star.title": "几何星",
            "pattern.geo-star.note": "星形几何为新开始而画——台阶上平静均匀的尖角。",
            "pattern.festival-flower.title": "节日花卉兰戈利",
            "pattern.festival-flower.note": "万寿菊瓣是家中迎客时常见的节日地面。",
            "pattern.mandala.title": "曼陀罗兰戈利",
            "pattern.mandala.note": "层层曼陀罗是更长的专注誓言，常用于九夜节与新年。",
            "pattern.butterfly.title": "蝴蝶兰戈利",
            "pattern.butterfly.note": "春日庭院为欧南节与乌加迪节画蝴蝶——泥土上的花园。",
            "pattern.pongal-pot.title": "丰收节陶罐兰戈利",
            "pattern.pongal-pot.note": "满溢的陶罐是泰丰收节：收获、甘蔗，与门口的欢腾。",
            "pattern.sikku-knot.title": "连环结科拉姆",
            "pattern.sikku-knot.note": "连环结是泰米尔经典——线不断，房屋被一条线缚住。",
            "pattern.onam-pookalam.title": "欧南节花毯",
            "pattern.onam-pookalam.note": "花毯是喀拉拉欧南节的鲜花地毯；本课用米粉画出那些圆环。",
            "pattern.sun-burst.title": "新年旭日",
            "pattern.sun-burst.note": "泰米尔新年与乌加迪节的朝阳——一年从门槛开启。",
            "pattern.mango-leaf.title": "芒果叶门饰",
            "pattern.mango-leaf.note": "芒果叶门饰在乌加迪节与排灯节悬挂并绘制，作为活的欢迎。",
